/* From Uiverse.io by Satwinder04 - Tags: input */
/* Input container */
.__UIV_SCOPE__ .input-container {
  position: relative;
  margin: 20px;
}

/* Input field */
.__UIV_SCOPE__ .input-field {
  display: block;
  width: 100%;
  padding: 10px;
  font-size: 16px;
  border: none;
  border-bottom: 2px solid #ccc;
  outline: none;
  background-color: transparent;
}

/* Input label */
.__UIV_SCOPE__ .input-label {
  position: absolute;
  top: 0;
  left: 0;
  font-size: 16px;
  color: rgba(204, 204, 204, 0);
  pointer-events: none;
  transition: all 0.3s ease;
}

/* Input highlight */
.__UIV_SCOPE__ .input-highlight {
  position: absolute;
  bottom: 0;
  left: 0;
  height: 2px;
  width: 0;
  background-color: #007bff;
  transition: all 0.3s ease;
}

/* Input field:focus styles */
.__UIV_SCOPE__ .input-field:focus + .input-label {
  top: -20px;
  font-size: 12px;
  color: #007bff;
}

.__UIV_SCOPE__ .input-field:focus + .input-label + .input-highlight {
  width: 100%;
}
